CREATE DEFINER=`root`@`localhost` FUNCTION `clean_category`(instr TEXT) RETURNS text CHARSET latin1
    DETERMINISTIC
    SQL SECURITY INVOKER
BEGIN
	SET @string = clean_name(instr);
	SET @string = REPLACE(@string, ' > ', '>');
	SET @string = REPLACE(@string, ' and ', ' &amp; ');
	RETURN @string;
END;
 ;;
delimiter ;

delimiter ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `clean_name`(instr TEXT) RETURNS text CHARSET latin1
    DETERMINISTIC
    SQL SECURITY INVOKER
BEGIN
	SET @string = instr;
	SET @string = REPLACE(@string, '&', '&amp;');
	SET @string = REPLACE(@string, ' / ', '/');
	RETURN @string;
END;
 ;;
delimiter ;

delimiter ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `find_category`(raw TEXT) RETURNS text CHARSET latin1
    READS SQL DATA
    DETERMINISTIC
    SQL SECURITY INVOKER
BEGIN
	RETURN SUBSTRING_INDEX(raw , '>', -1);
END;
 ;;
delimiter ;

